#!/usr/bin/env node
/*
 * vm.js - MIPS32r2 (o32, little-endian) user-mode interpreter with Linux-style
 * syscall emulation, sufficient to boot doomgeneric_mips and let it render and
 * save frames (the guest writes /tmp/frame.bmp itself through open/write/close).
 *
 * Usage: node vm.js [elf-file]
 */
'use strict';

const fs = require('fs');
const path = require('path');

/* ------------------------------------------------------------------ memory */

// Guest layout (flat, physical == virtual):
//   0x00400000 .text/.rodata
//   0x00466520 .data/.bss (includes a 1GB static heap) -> ends ~0x4046B790
//   stack top  0x40F00000 (grows down)
const MEM_SIZE = 0x41000000; // 1.015 GiB, covers all of the above
const STACK_TOP = 0x40F00000;

const membuf = new ArrayBuffer(MEM_SIZE);
const U8 = new Uint8Array(membuf);
const I8 = new Int8Array(membuf);
const U16 = new Uint16Array(membuf);
const I16 = new Int16Array(membuf);
const U32 = new Uint32Array(membuf);
const I32 = new Int32Array(membuf);

function fault(kind, addr, pc) {
  throw new Error(
    kind + ' fault at 0x' + (addr >>> 0).toString(16) +
    ' (pc=0x' + (pc >>> 0).toString(16) + ')');
}

function chk(a) {
  if ((a >>> 0) >= MEM_SIZE) fault('memory', a, PC);
  return a;
}

/* unaligned-tolerant accessors (aligned cases are inlined in the main loop) */
function rd32(a) {
  chk(a); chk(a + 3);
  return (U8[a] | (U8[a + 1] << 8) | (U8[a + 2] << 16) | (U8[a + 3] << 24)) | 0;
}
function wr32(a, v) {
  chk(a); chk(a + 3);
  U8[a] = v; U8[a + 1] = v >>> 8; U8[a + 2] = v >>> 16; U8[a + 3] = v >>> 24;
}
function rd16(a) { chk(a); chk(a + 1); return (U8[a] | (U8[a + 1] << 8)); }
function wr16(a, v) { chk(a); chk(a + 1); U8[a] = v; U8[a + 1] = v >>> 8; }

function readCString(addr) {
  let end = addr >>> 0;
  while (end < MEM_SIZE && U8[end] !== 0) end++;
  return Buffer.from(membuf, addr >>> 0, end - (addr >>> 0)).toString('latin1');
}

/* --------------------------------------------------------------- elf loader */

function loadElf(file) {
  const b = fs.readFileSync(file);
  if (!(b[0] === 0x7f && b[1] === 0x45 && b[2] === 0x4c && b[3] === 0x46))
    throw new Error('not an ELF file: ' + file);
  if (b[4] !== 1) throw new Error('only ELF32 supported');
  if (b[5] !== 1) throw new Error('only little-endian ELF supported');
  const entry = b.readUInt32LE(24);
  const phoff = b.readUInt32LE(28);
  const phentsize = b.readUInt16LE(42);
  const phnum = b.readUInt16LE(44);
  let gp = 0;
  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    const type = b.readUInt32LE(o);
    const off = b.readUInt32LE(o + 4);
    const vaddr = b.readUInt32LE(o + 8);
    const filesz = b.readUInt32LE(o + 16);
    const memsz = b.readUInt32LE(o + 20);
    if (type === 1 /* PT_LOAD */) {
      if (vaddr + memsz > MEM_SIZE)
        throw new Error('segment 0x' + vaddr.toString(16) + '+0x' +
          memsz.toString(16) + ' does not fit in emulated memory');
      b.copy(U8, vaddr, off, off + filesz); // rest of memsz is already zero
    } else if (type === 0x70000000 /* PT_MIPS_REGINFO */) {
      // ri_gp_value is the last word of the 24-byte .reginfo blob
      if (filesz >= 24) gp = b.readUInt32LE(off + 20);
    }
  }
  return { entry: entry | 0, gp: gp | 0 };
}

/* ------------------------------------------------------------------- state */

const R = new Int32Array(32);   // general purpose registers
let HI = 0, LO = 0;
let PC = 0;

// FPU: FR=1 layout (32 x 64-bit registers; singles live in the low half)
const fpbuf = new ArrayBuffer(32 * 8);
const FU32 = new Uint32Array(fpbuf);
const FI32 = new Int32Array(fpbuf);
const F32 = new Float32Array(fpbuf);
const F64 = new Float64Array(fpbuf);
const FCC = new Uint8Array(8);
let FCSR = 0;

/* ------------------------------------------------------------- 64-bit muls */

function mulHiS(a, b) {
  const a0 = a & 0xffff, a1 = a >> 16;
  const b0 = b & 0xffff, b1 = b >> 16;
  const p0 = a0 * b0;
  const mid = (p0 >>> 16) + a1 * b0 + a0 * b1;
  return (a1 * b1 + Math.floor(mid / 65536)) | 0;
}
function mulHiU(a, b) {
  a = a >>> 0; b = b >>> 0;
  const a0 = a & 0xffff, a1 = a >>> 16;
  const b0 = b & 0xffff, b1 = b >>> 16;
  const p0 = a0 * b0;
  const mid = (p0 >>> 16) + a1 * b0 + a0 * b1;
  return (a1 * b1 + Math.floor(mid / 65536)) | 0;
}

/* ---------------------------------------------------------------- syscalls */

const SYS = {
  read: 0, write: 1, open: 2, close: 3, stat: 4, fstat: 5, lstat: 6,
  lseek: 8, mmap: 9, brk: 12, ioctl: 16, nanosleep: 35, getpid: 39,
  exit: 60, exit_group: 231, fsync: 74, ftruncate: 77, getcwd: 79,
  rename: 82, mkdir: 83, rmdir: 84, unlink: 87, gettimeofday: 96,
  clock_gettime: 228, time: 201,
