  }
  if (f & 64) out |= OF.O_CREAT;
  if (f & 128) out |= OF.O_EXCL;
  if (f & 512) out |= OF.O_TRUNC;
  if (f & 1024) out |= OF.O_APPEND;
  return out;
}

// Guest file offsets are tracked here so that lseek/read/write are explicit.
const fpos = new Map();

function resolvePath(p, forWrite) {
  if (path.isAbsolute(p)) return p;
  const cwdRel = path.resolve(process.cwd(), p);
  if (fs.existsSync(cwdRel) || forWrite) return cwdRel;
  const dirRel = path.resolve(__dirname, p);
  if (fs.existsSync(dirRel)) return dirRel;
  return cwdRel;
}

function errnoOf(e) {
  const map = {
    ENOENT: 2, EACCES: 13, EEXIST: 17, EISDIR: 21, ENOTDIR: 20, EBADF: 9,
    EINVAL: 22, ENOSPC: 28, EMFILE: 24, ENOTEMPTY: 39, EPERM: 1, EIO: 5,
  };
  return map[e.code] !== undefined ? map[e.code] : EIO;
}

let exitCode = null;

function doSyscall() {
  const num = R[2] | 0;
  const a0 = R[4] | 0, a1 = R[5] | 0, a2 = R[6] | 0, a3 = R[7] | 0;
