        if (fd === 0) { // stdin: no input available
          return 0;
        }
        const pos = fpos.has(fd) ? fpos.get(fd) : 0;
        const n = fs.readSync(fd, U8, addr, len, pos);
        fpos.set(fd, pos + n);
        return n;
      }
      case SYS.write: {
        const fd = a0, addr = a1 >>> 0, len = a2 | 0;
        if (len < 0) return -EINVAL;
        if (len === 0) return 0;
        chk(addr); chk(addr + len - 1);
        if (fd === 0 || fd === 1 || fd === 2) {
          const hfd = fd === 2 ? 2 : 1;
          const buf = Buffer.from(membuf, addr, len);
          let done = 0;
          while (done < len) {
            try {
              done += fs.writeSync(hfd, buf, done, len - done);
            } catch (e) {
              if (e.code === 'EAGAIN') continue;
              throw e;
            }
          }
