/* -------------------------------------------------------------------- main */

function main() {
  const elfPath = process.argv[2] || path.join(__dirname, 'doomgeneric_mips');
  const { entry, gp } = loadElf(elfPath);
  let code = 0;
  try {
    code = run(entry, gp) | 0;
  } catch (e) {
    process.stderr.write('vm: ' + (e && e.stack ? e.stack : String(e)) + '\n');
    process.stderr.write('vm: instructions executed: ' + ICOUNT + '\n');
    process.exitCode = 1;
    return;
  }
  process.exitCode = code;
}

